import Flutter
import Foundation
import NetworkExtension

/// iOS implementation of VpnHostApi generated by Pigeon, controlling NETunnelProviderManager.
class IosVpnBridgeHandler: NSObject, VpnHostApi, FlutterStreamHandler {

    private let messenger: FlutterBinaryMessenger
    private var vpnManager: NETunnelProviderManager?
    private var statusEventSink: FlutterEventSink?
    private var statsEventSink: FlutterEventSink?
    private var activeProfileName: String?
    private var connectedAtDate: Date?
    private var statsTimer: Timer?

    private let appGroupIdentifier = "group.com.ramez.tunnel_plus"
    private let tunnelBundleIdentifier = "com.ramez.tunnel_plus.PacketTunnel"

    init(messenger: FlutterBinaryMessenger) {
        self.messenger = messenger
        super.init()

        // 1. Setup Status EventChannel
        let statusChannel = FlutterEventChannel(name: "com.ramez.tunnel_plus/vpn_status", binaryMessenger: messenger)
        statusChannel.setStreamHandler(self)

        // 2. Setup Stats EventChannel
        let statsChannel = FlutterEventChannel(name: "com.ramez.tunnel_plus/vpn_stats", binaryMessenger: messenger)
        statsChannel.setStreamHandler(StatsStreamHandler(handler: self))

        // 3. Observe OS NEVPNStatusDidChange Notifications
        NotificationCenter.default.addObserver(
            self,
            selector: #selector(vpnStatusDidChange(_:)),
            name: .NEVPNStatusDidChange,
            object: nil
        )

        // Load existing manager on initialization
        loadManager(nil)
    }

    private func loadManager(_ completion: ((NETunnelProviderManager?) -> Void)?) {
        NETunnelProviderManager.loadAllFromPreferences { [weak self] managers, error in
            guard let self = self else { return }
            if let manager = managers?.first {
                self.vpnManager = manager
                completion?(manager)
            } else {
                let newManager = NETunnelProviderManager()
                let proto = NETunnelProviderProtocol()
                proto.providerBundleIdentifier = self.tunnelBundleIdentifier
                proto.serverAddress = "127.0.0.1"
                newManager.protocolConfiguration = proto
                newManager.localizedDescription = "Ramez Tunnel Plus"
                self.vpnManager = newManager
                completion?(newManager)
            }
        }
    }

    // MARK: - VpnHostApi Implementation

    func prepare(completion: @escaping (Result<Bool, Error>) -> Void) {
        loadManager { manager in
            guard let manager = manager else {
                completion(.success(false))
                return
            }

            manager.isEnabled = true
            manager.saveToPreferences { error in
                if let error = error {
                    completion(.failure(PigeonError(code: "PREPARE_FAILED", message: error.localizedDescription, details: nil)))
                } else {
                    // Successfully saved to OS Preferences (triggers iOS permission prompt if first time)
                    completion(.success(true))
                }
            }
        }
    }

    func connect(profile: VpnProfilePayload, completion: @escaping (Result<Bool, Error>) -> Void) {
        loadManager { [weak self] manager in
            guard let self = self, let manager = manager else {
                completion(.failure(PigeonError(code: "NO_MANAGER", message: "VPN Manager unavailable", details: nil)))
                return
            }

            self.activeProfileName = profile.name
            let proto = (manager.protocolConfiguration as? NETunnelProviderProtocol) ?? NETunnelProviderProtocol()
            proto.providerBundleIdentifier = self.tunnelBundleIdentifier
            proto.serverAddress = profile.serverAddress

            // Pass configuration parameters to the PacketTunnel extension
            proto.providerConfiguration = [
                "id": profile.id,
                "name": profile.name,
                "protocol": profile.protocol,
                "serverAddress": profile.serverAddress,
                "serverPort": profile.serverPort,
                "rawPayload": profile.rawPayload,
                "dnsServers": profile.dnsServers,
                "bypassLan": profile.bypassLan
            ]

            manager.protocolConfiguration = proto
            manager.isEnabled = true

            manager.saveToPreferences { error in
                if let error = error {
                    completion(.failure(PigeonError(code: "SAVE_FAILED", message: error.localizedDescription, details: nil)))
                    return
                }

                manager.loadFromPreferences { error in
                    if let error = error {
                        completion(.failure(PigeonError(code: "LOAD_FAILED", message: error.localizedDescription, details: nil)))
                        return
                    }

                    do {
                        let tunnelOptions: [String: NSObject] = [
                            "serverAddress": profile.serverAddress as NSString,
                            "protocol": profile.protocol as NSString
                        ]
                        try manager.connection.startVPNTunnel(options: tunnelOptions)
                        self.connectedAtDate = Date()
                        self.startStatsPolling()
                        completion(.success(true))
                    } catch {
                        completion(.failure(PigeonError(code: "START_FAILED", message: error.localizedDescription, details: nil)))
                    }
                }
            }
        }
    }

    func disconnect(completion: @escaping (Result<Bool, Error>) -> Void) {
        guard let manager = vpnManager else {
            completion(.success(true))
            return
        }

        manager.connection.stopVPNTunnel()
        stopStatsPolling()
        activeProfileName = nil
        connectedAtDate = nil
        completion(.success(true))
    }

    func getStatus() throws -> VpnStatusPayload {
        let status = vpnManager?.connection.status ?? .disconnected
        return mapVpnStatus(status)
    }

    func listEngines() throws -> [VpnEngineInfo] {
        return [
            VpnEngineInfo(
                id: "network_extension_core",
                name: "Apple NEPacketTunnel Core",
                supportedProtocols: ["openvpn", "wireguard", "ssh", "vless", "vmess"],
                version: "Apple iOS 17/18 SDK"
            ),
            VpnEngineInfo(
                id: "wireguard_apple_core",
                name: "WireGuard Apple Native",
                supportedProtocols: ["wireguard"],
                version: "1.0.2023"
            ),
            VpnEngineInfo(
                id: "singbox_apple_core",
                name: "SingBox Apple Core",
                supportedProtocols: ["vless", "vmess", "trojan", "shadowsocks"],
                version: "1.9.0"
            )
        ]
    }

    // MARK: - Status Mapping & Notification Handling

    @objc private func vpnStatusDidChange(_ notification: Notification) {
        guard let connection = notification.object as? NEVPNConnection else { return }
        let payload = mapVpnStatus(connection.status)

        let statusMap: [String: Any?] = [
            "state": payload.state,
            "connectedServerName": payload.connectedServerName,
            "errorMessage": payload.errorMessage,
            "connectedAtIso": payload.connectedAtIso
        ]

        DispatchQueue.main.async { [weak self] in
            self?.statusEventSink?(statusMap)
        }
    }

    private func mapVpnStatus(_ status: NEVPNStatus) -> VpnStatusPayload {
        let isoFormatter = ISO8601DateFormatter()
        let connectedIso = connectedAtDate.map { isoFormatter.string(from: $0) }

        switch status {
        case .connected:
            return VpnStatusPayload(state: "connected", connectedServerName: activeProfileName, errorMessage: nil, connectedAtIso: connectedIso)
        case .connecting:
            return VpnStatusPayload(state: "connecting", connectedServerName: activeProfileName, errorMessage: nil, connectedAtIso: nil)
        case .reasserting:
            return VpnStatusPayload(state: "reconnecting", connectedServerName: activeProfileName, errorMessage: nil, connectedAtIso: connectedIso)
        case .disconnecting:
            return VpnStatusPayload(state: "disconnected", connectedServerName: nil, errorMessage: nil, connectedAtIso: nil)
        case .disconnected, .invalid:
            return VpnStatusPayload(state: "disconnected", connectedServerName: nil, errorMessage: nil, connectedAtIso: nil)
        @unknown default:
            return VpnStatusPayload(state: "disconnected", connectedServerName: nil, errorMessage: nil, connectedAtIso: nil)
        }
    }

    // MARK: - FlutterStreamHandler for Status

    func onListen(withArguments arguments: Any?, eventSink events: @escaping FlutterEventSink) -> FlutterError? {
        self.statusEventSink = events
        let current = try? getStatus()
        if let current = current {
            events([
                "state": current.state,
                "connectedServerName": current.connectedServerName,
                "errorMessage": current.errorMessage,
                "connectedAtIso": current.connectedAtIso
            ])
        }
        return nil
    }

    func onCancel(withArguments arguments: Any?) -> FlutterError? {
        self.statusEventSink = nil
        return nil
    }

    // MARK: - Stats Polling via Extension IPC

    private func startStatsPolling() {
        stopStatsPolling()
        statsTimer = Timer.scheduledTimer(withTimeInterval: 1.0, repeats: true) { [weak self] _ in
            self?.queryTunnelStats()
        }
    }

    private func stopStatsPolling() {
        statsTimer?.invalidate()
        statsTimer = nil
    }

    private func queryTunnelStats() {
        guard let connection = vpnManager?.connection as? NETunnelProviderSession else { return }
        guard let messageData = "GET_STATS".data(using: .utf8) else { return }

        do {
            try connection.sendProviderMessage(messageData) { [weak self] responseData in
                guard let self = self, let data = responseData else { return }
                guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return }

                let bytesIn = json["bytesIn"] as? Int ?? 0
                let bytesOut = json["bytesOut"] as? Int ?? 0
                let duration = json["durationSeconds"] as? Int ?? 0

                let statsMap: [String: Any] = [
                    "bytesIn": bytesIn,
                    "bytesOut": bytesOut,
                    "downloadSpeedBps": max(0, bytesIn / max(1, duration)),
                    "uploadSpeedBps": max(0, bytesOut / max(1, duration)),
                    "durationSeconds": duration
                ]

                DispatchQueue.main.async {
                    self.statsEventSink?(statsMap)
                }
            }
        } catch {
            // Extension busy or stopping
        }
    }

    fileprivate class StatsStreamHandler: NSObject, FlutterStreamHandler {
        private weak var handler: IosVpnBridgeHandler?
        init(handler: IosVpnBridgeHandler) { self.handler = handler }

        func onListen(withArguments arguments: Any?, eventSink events: @escaping FlutterEventSink) -> FlutterError? {
            handler?.statsEventSink = events
            return nil
        }
        func onCancel(withArguments arguments: Any?) -> FlutterError? {
            handler?.statsEventSink = nil
            return nil
        }
    }
}
